function XUiLuckyTenant2Chess:SetTab(tab)
    if self._Tab == tab then
        return
    end

    if self.PlayAnimation then
        self:PlayAnimation("Switch")
    end

    self._Tab = tab

    if tab == Tab.AddPiece then
        if self.SelectPiecePanel then
            self.SelectPiecePanel.gameObject:SetActiveEx(true)
        end
        -- 关闭背包相关的Grid
        if self._Grids then
            for i = 1, #self._Grids do
                local grid = self._Grids[i]
                if grid and grid.Close then
                    grid:Close()
                end
            end
        end
        if self._Detail and self._Detail.Close then
            self._Detail:Close()
        end
        if self.BagPanel then
            self.BagPanel.gameObject:SetActiveEx(false)
        end
        if self.PanelDelete then
            self.PanelDelete.gameObject:SetActiveEx(false)
        end
        -- 隐藏所有删除相关的按钮
        if self.BtnDeleteNoFree then
            self.BtnDeleteNoFree.gameObject:SetActiveEx(false)
        end

        if not self:UpdateAddPiece() then
            return
        end
        self:UpdateProp()
        if self.BtnBag and self._Control then
            local uiData = self._Control:GetUiData()
            if self.BtnBag.SetNameByGroup then
                self.BtnBag:SetNameByGroup(0, uiData.PiecesAmount or 0)
            end
        end
        return
    end

    if tab == Tab.Bag then
        if self.SelectPiecePanel then
            self.SelectPiecePanel.gameObject:SetActiveEx(false)
        end
        if self.BagPanel then
            self.BagPanel.gameObject:SetActiveEx(true)
        end
        if self.PanelDelete then
            self.PanelDelete.gameObject:SetActiveEx(true)
        end
        -- 只显示消耗道具的删除按钮（与 InitComponents 一致）
        if self.BtnDeleteNoFree then
            self.BtnDeleteNoFree.gameObject:SetActiveEx(true)
        end
        self:UpdateBag()
        return
    end

    XLog.Error("[XUiLuckyTenant2Chess] 未定义的页签")
end

